"""Mesh-only station spacing and final-coordinate quad checks.

Analytic curvature breaks and clearance samples are not removed. A copied
table changes only which breaks demand mesh columns. This fallback must pass
the same surface checks and final-coordinate convexity check as the original.
"""
import bpy
from . import curved_junction_nodes as boundary
c=boundary.c


def mesh_break_table():
    """Expose mesh-only spacing for explicit experimental graph composition.

    The complete clearance/depth table survives. Only mesh-column flags change;
    this does not authorize changing an analytic corner or a profile constraint.
    A caller must qualify the resulting boundary discretization independently.
    """
    name='Prochitecture Streets / Mesh-only break spacing v1'
    if name in bpy.data.node_groups:return bpy.data.node_groups[name]
    g=c.Graph(name)
    g.socket('Geometry','NodeSocketGeometry');g.socket('Cell Size','NodeSocketFloat')
    g.socket('Geometry','NodeSocketGeometry','OUTPUT')
    inp=g.node('NodeGroupInput');out=g.node('NodeGroupOutput')
    g.bind(spaced_breaks(g,inp.outputs['Geometry'],inp.outputs['Cell Size']),out.inputs['Geometry'])
    return g.g


def spaced_breaks(g,table,cell):
    """Keep endpoints and greedily space interior mesh stations by 1% of cell."""
    index=c.V(g,g.node('GeometryNodeInputIndex').outputs[0])
    marked=c._store(g,table,'_mp_original',index,'INT')
    knots=c._select(g,marked,c.named(g,'st_cg_break','BOOLEAN'))
    count=c._count(g,knots)
    ri=g.node('GeometryNodeRepeatInput','Keep analytic samples; space only mesh columns')
    ro=g.node('GeometryNodeRepeatOutput');ro.repeat_items.new('FLOAT','Last')
    ro.repeat_items.new('INT','Owner');ri.pair_with_output(ro)
    g.bind(count,ri.inputs['Iterations']);ri.inputs['Owner'].default_value=-1
    at=c.V(g,ri.outputs['Iteration']);owner=c._read(g,knots,'st_cg_owner',at,'INT')
    t=c._read(g,knots,'st_cg_t',at);length=c._read(g,knots,'st_cg_length',at)
    spacing=.01*g.math('MAXIMUM',c.V(g,cell),.02)
    same=g.math('COMPARE',owner,c.V(g,ri.outputs['Owner']))
    # 1 - 1e-8 rounds back to 1 in float32. Use inclusive comparisons to
    # retain the exact final endpoint instead of an unrepresentable epsilon.
    endpoint=2.-g.math('GREATER_THAN',t,0.)-g.math('LESS_THAN',t,1.)
    room=g.math('GREATER_THAN',(t-c.V(g,ri.outputs['Last']))*length,spacing)
    room=room*g.math('GREATER_THAN',(1.-t)*length,spacing)
    keep=g.math('MAXIMUM',endpoint,(1.-same)+room)
    row=c._select(g,knots,g.math('COMPARE',index,at))
    g.bind(boundary._join(g,ri.outputs['Geometry'],boundary._empty(g,row,keep)),ro.inputs['Geometry'])
    g.bind(c.choose(g,keep,t,c.V(g,ri.outputs['Last'])),ro.inputs['Last']);g.bind(owner,ro.inputs['Owner'])
    retained=g.setpos(ro.outputs['Geometry'],g.xyz(c.named(g,'_mp_original','INT')))
    nearest=g.node('GeometryNodeSampleNearest');nearest.domain='POINT'
    g.bind(retained,nearest.inputs['Geometry']);g.bind(g.xyz(index),nearest.inputs['Sample Position'])
    original=c._read(g,retained,'_mp_original',nearest.outputs['Index'],'INT')
    return c._store(g,table,'st_cg_break',g.math('COMPARE',original,index),'BOOLEAN')


def positive_quads(g,geometry):
    """Check the published float32 XY, including translation rounding."""
    face=c.V(g,g.node('GeometryNodeInputIndex').outputs[0]);points=[];valid=1.
    for corner in range(4):
        at=g.node('GeometryNodeCornersOfFace');g.bind(face,at.inputs['Face Index'])
        at.inputs['Sort Index'].default_value=corner
        vertex=g.node('GeometryNodeVertexOfCorner');g.bind(at.outputs['Corner Index'],vertex.inputs['Corner Index'])
        point=c._sample(g,geometry,g.position(),vertex.outputs['Vertex Index'],'FLOAT_VECTOR')
        points.append(c._vec(g,point))
        valid=valid*g.math('COMPARE',at.outputs['Total'],4.)
    for i in range(4):
        a=c._sub(points[(i+1)%4],points[i]);b=c._sub(points[(i+2)%4],points[(i+1)%4])
        valid=valid*g.math('GREATER_THAN',c._cross(a,b),1e-9)
    return g.math('GREATER_THAN',c._count(g,geometry),3.5)*c._stat(g,geometry,valid,domain='FACE')
